// Stufenlogik aus dem Standardprozess-Dokument – NUR die Struktur.
// Die Texte selbst liegen als Vorlagen im n8n-Data-Store (Schlüssel unten),
// niemals in dieser Datei.
const k = $input.first().json;
const stufe = (k.followUpStufe ?? 0) + 1;
const max = k.maxStufen ?? 3; // Workshop-Frage: 3 (Angebot) vs. offene Kette (Standardprozess)
let vorlage;
let zielregionenFrage = false;
if (stufe === 1) {
  vorlage = 'followup-1'; // feste Vorlage 1
} else if (stufe === 2) {
  vorlage = 'followup-2'; // feste Vorlage 2
  // Beschluss Demo-Check: Stufe 2 fragt aktiv nach aktuellen Zielregionen –
  // die Antwort pflegt das Ankaufsprofil (WF 06 erkennt und übernimmt sie).
  zielregionenFrage = true;
} else if (stufe >= max) {
  vorlage = 'followup-final'; // Final-Mail: kündigt das Ende der Kette an
} else {
  // weitere Stufen: zwei alternierende Vorlagen (Standardprozess)
  vorlage = stufe % 2 === 1 ? 'followup-a' : 'followup-b';
}
return [{ json: { ...k, neueStufe: stufe, vorlage, zielregionenFrage, istFinal: stufe >= max, bccLeitung: k.bccLeitung ?? '' } }];
